package app.sonicsound.remote

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.math.BigInteger
import java.security.KeyFactory
import java.security.KeyPair
import java.security.interfaces.ECPublicKey
import java.security.spec.ECPoint
import java.security.spec.ECPrivateKeySpec
import java.security.spec.ECPublicKeySpec
import java.util.Base64

class QuickConnectCryptoTest {
    // Generated by src/quickconnect/qcCrypto.ts (see qcCrypto.test.ts) — proves JS ↔ Kotlin interop.
    private val tvPub = "BAIX5hfwtkQ5KCePlpmeaaI6TywVK99tbN9m5bgCgtTtGUp968uXcS0t2jyoWqh2Wlb0X8dYWZZS8ol8ZTBuV5Q="
    private val jsSealed = QuickConnectSealed(
        clientPub = "BNZak5d8qj0bCBhS/1ennkZfFmBXcwS66tUF3TpIWJzzUBheiVNy32Ih6joTdVfkc/3bZ1XwW9UHw8Uz/OnJEoU=",
        nonce = "MzMzMzMzMzMzMzMz",
        ct = "m+Pg3DYPZ6lny3us8GUUnEyfcKpW2BH2Qw==",
    )

    private fun fixedTvKeys(): KeyPair {
        val params = (QuickConnectCrypto.generateKeyPair().public as ECPublicKey).params
        val raw = Base64.getDecoder().decode(tvPub)
        val point = ECPoint(
            BigInteger(1, raw.copyOfRange(1, 33)),
            BigInteger(1, raw.copyOfRange(33, 65)),
        )
        val factory = KeyFactory.getInstance("EC")
        val public = factory.generatePublic(ECPublicKeySpec(point, params))
        val private = factory.generatePrivate(ECPrivateKeySpec(BigInteger("1".repeat(64), 16), params))
        return KeyPair(public, private)
    }

    @Test
    fun opensEnvelopeSealedByJavaScript() {
        val keys = fixedTvKeys()
        assertEquals(tvPub, QuickConnectCrypto.publicKeyBase64(keys))
        assertEquals("{\"u\":\"x\"}", QuickConnectCrypto.open(keys, "482913", jsSealed))
        assertNull(QuickConnectCrypto.open(keys, "000000", jsSealed))
    }

    @Test
    fun kotlinSealRoundTrips() {
        val keys = QuickConnectCrypto.generateKeyPair()
        val sealed = QuickConnectCrypto.seal(QuickConnectCrypto.publicKeyBase64(keys), "123456", "secret")
        assertEquals("secret", QuickConnectCrypto.open(keys, "123456", sealed))
        assertNull(QuickConnectCrypto.open(keys, "654321", sealed))
    }

    @Test
    fun sessionLocksAfterMaxWrongCodes() {
        val code = QuickConnect.start(nowMs = 0)
        val wrong = if (code == "000000") "111111" else "000000"
        val sealed = QuickConnectCrypto.seal(QuickConnect.publicKey(nowMs = 0)!!, wrong, "x")
        repeat(QuickConnect.MAX_ATTEMPTS) {
            assertTrue(QuickConnect.open(sealed, nowMs = 0) is QuickConnect.OpenResult.Rejected)
        }
        assertTrue(!QuickConnect.isActive(nowMs = 0))
    }

    @Test
    fun sessionExpires() {
        QuickConnect.start(nowMs = 0)
        assertTrue(QuickConnect.isActive(nowMs = QuickConnect.SESSION_MS - 1))
        assertTrue(!QuickConnect.isActive(nowMs = QuickConnect.SESSION_MS))
        QuickConnect.stop()
    }
}
